import * as T from '../vendor/three.module.js';
// Alia's sfx (BrassHorizon-7501e781-023 deck cannon, -025 salvage chime): decoded on start, layered into the master bus; missing files fall back to the synth.
const SFX_BASE=new URL(import.meta.url.includes('/dist/')?'../../assets/':'../assets/',import.meta.url).href;
export class Sound{
 constructor(){this.enabled=false;this.ctx=null;this.sfx={};this.lastChime=0;}
 load(n){if(n in this.sfx||!this.ctx)return;this.sfx[n]=null;fetch(SFX_BASE+n).then(r=>{if(!r.ok)throw 0;return r.arrayBuffer()}).then(b=>this.ctx.decodeAudioData(b)).then(b=>this.sfx[n]=b).catch(()=>this.sfx[n]=false);}
 sample(n,vol=1,rate=1){if(!this.enabled||!this.ctx||!this.sfx[n])return false;const s=this.ctx.createBufferSource(),g=this.ctx.createGain();s.buffer=this.sfx[n];s.playbackRate.value=rate;g.gain.value=vol;s.connect(g).connect(this.master);s.start();return true;}
 toggle(){this.enabled=!this.enabled;if(this.enabled)this.start();if(this.ctx)this.ctx.resume();return this.enabled;}
 start(){if(this.ctx)return;const A=window.AudioContext||window.webkitAudioContext;if(!A)return;this.ctx=new A();let c=this.ctx;this.master=c.createGain();this.master.gain.value=.3;this.master.connect(c.destination);this.engine=c.createOscillator();this.engine.type='sawtooth';this.engine.frequency.value=38;this.eg=c.createGain();this.eg.gain.value=.025;let filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=100;this.engine.connect(filter).connect(this.eg).connect(this.master);this.engine.start();let len=c.sampleRate*2;this.noise=c.createBuffer(1,len,c.sampleRate);let data=this.noise.getChannelData(0);for(let i=0;i<len;i++)data[i]=Math.random()*2-1;this.load('sfx_cannon.ogg');this.load('sfx_salvage_chime.ogg');}
 update(speed){if(this.ctx){this.master.gain.setTargetAtTime(this.enabled?.35:0,this.ctx.currentTime,.15);this.engine.frequency.setTargetAtTime(32+Math.abs(speed)*1.2,this.ctx.currentTime,.3);}}
 hit(type='fire',strength=1){if(!this.enabled||!this.ctx)return;if(type==='fire'&&strength>=1&&this.sample('sfx_cannon.ogg',1.5,.95+Math.random()*.1))return;if(type==='collect'){const now=performance.now();if(now-this.lastChime<80)return;this.lastChime=now;if(this.sample('sfx_salvage_chime.ogg',.9,.96+Math.random()*.08))return;}let c=this.ctx,t=c.currentTime;let g=c.createGain(),o=c.createOscillator(),dur=type==='collect'?.13:type==='upgrade'?.8:.55;g.connect(this.master);g.gain.setValueAtTime((type==='collect'?.07:.5)*Math.min(strength,1.5),t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.type=type==='collect'||type==='upgrade'?'sine':'triangle';o.frequency.setValueAtTime(type==='fire'?95:type==='collect'?720:type==='upgrade'?240:65,t);o.frequency.exponentialRampToValueAtTime(type==='collect'?1200:type==='upgrade'?960:25,t+dur);o.connect(g);o.start(t);o.stop(t+dur);
 if(type==='fire'||type==='blast'){let n=c.createBufferSource();n.buffer=this.noise;let f=c.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(type==='fire'?1400:700,t);let ng=c.createGain();ng.gain.setValueAtTime(.4,t);ng.gain.exponentialRampToValueAtTime(.001,t+dur);n.connect(f).connect(ng).connect(this.master);n.start();n.stop(t+dur);}}
}
export class Effects{
 constructor(scene){this.scene=scene;this.max=700;this.items=[];this.index=0;this.dummy=new T.Object3D();this.mesh=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:0xc4a26b,roughness:.8,metalness:.3}),this.max);this.mesh.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(this.mesh);this.mesh.frustumCulled=false;for(let i=0;i<this.max;i++){this.mesh.setMatrixAt(i,new T.Matrix4().makeScale(0,0,0));this.items.push({life:0});}
 this.glows=[];this.rings=[];this.light=new T.PointLight(0xff9c35,0,250,2);scene.add(this.light);this.budget=25;
 const cvs=document.createElement('canvas');cvs.width=64;cvs.height=64;let c=cvs.getContext('2d');let g=c.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'rgba(255,245,180,1)');g.addColorStop(.2,'rgba(255,166,54,.9)');g.addColorStop(.6,'rgba(190,75,10,.35)');g.addColorStop(1,'rgba(80,30,0,0)');c.fillStyle=g;c.fillRect(0,0,64,64);this.texture=new T.CanvasTexture(cvs);
 this.smoke=[];const sCanvas=document.createElement('canvas');sCanvas.width=64;sCanvas.height=64;let sc=sCanvas.getContext('2d'),sg=sc.createRadialGradient(32,32,0,32,32,32);sg.addColorStop(0,'rgba(70,69,61,.2)');sg.addColorStop(.5,'rgba(60,65,60,.12)');sg.addColorStop(1,'rgba(60,65,60,0)');sc.fillStyle=sg;sc.fillRect(0,0,64,64);this.smokeTex=new T.CanvasTexture(sCanvas);
 }
 burst(pos,power=1){for(let i=0;i<this.budget;i++){let k=this.index++%this.max;this.items[k]={life:1.3+Math.random()*1.7,max:3,pos:pos.clone(),vel:new T.Vector3((Math.random()-.5)*35,Math.random()*35,(Math.random()-.5)*35).multiplyScalar(power),rot:new T.Vector3(Math.random()*6,Math.random()*6,0),size:Math.random()*1.7+.3};}
 if(power<1)return;
 let sp=new T.Sprite(new T.SpriteMaterial({map:this.texture,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));sp.position.copy(pos);sp.scale.setScalar(25*power);this.scene.add(sp);this.glows.push({sp,life:.65,size:25*power});if(this.glows.length>20){let old=this.glows.shift();this.scene.remove(old.sp);old.sp.material.dispose();}
 let ring=new T.Mesh(new T.RingGeometry(.94,1,48),new T.MeshBasicMaterial({color:0xffbf64,side:T.DoubleSide,transparent:true,opacity:.8,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.copy(pos);this.scene.add(ring);this.rings.push({mesh:ring,life:.6});this.light.position.copy(pos).add(new T.Vector3(0,7,0));this.light.intensity=12000*power;
 }
 smokeAt(p){if(this.smoke.length>90)return;let sp=new T.Sprite(new T.SpriteMaterial({map:this.smokeTex,transparent:true,depthWrite:false,opacity:.45}));sp.position.copy(p);sp.scale.setScalar(15);this.scene.add(sp);this.smoke.push({sp,life:6,max:6});}
 update(dt){let d=this.dummy;for(let i=0;i<this.max;i++){let p=this.items[i];if(p.life<=0)continue;p.life-=dt;if(p.life>0){p.vel.y-=dt*17;p.pos.addScaledVector(p.vel,dt);p.rot.x+=dt*2;p.rot.y+=dt;d.position.copy(p.pos);d.rotation.set(p.rot.x,p.rot.y,0);d.scale.setScalar(p.size*Math.min(1,p.life*2));}else d.scale.setScalar(0);d.updateMatrix();this.mesh.setMatrixAt(i,d.matrix);}this.mesh.instanceMatrix.needsUpdate=true;
 for(let i=this.glows.length-1;i>=0;i--){let g=this.glows[i];g.life-=dt;g.sp.material.opacity=Math.max(0,g.life/.65);g.sp.scale.setScalar(g.size*(1+(1-g.life/.65)*1.5));if(g.life<=0){this.scene.remove(g.sp);g.sp.material.dispose();this.glows.splice(i,1);}}
 for(let i=this.rings.length-1;i>=0;i--){let r=this.rings[i];r.life-=dt;r.mesh.scale.setScalar(1+(1-r.life/.6)*65);r.mesh.material.opacity=Math.max(0,r.life);if(r.life<=0){this.scene.remove(r.mesh);r.mesh.geometry.dispose();r.mesh.material.dispose();this.rings.splice(i,1);}}
 for(let i=this.smoke.length-1;i>=0;i--){let p=this.smoke[i];p.life-=dt;p.sp.position.y+=dt*5;p.sp.position.x+=dt*2;p.sp.scale.setScalar(15+(1-p.life/p.max)*42);p.sp.material.opacity=.5*Math.min(1,p.life);if(p.life<=0){this.scene.remove(p.sp);p.sp.material.dispose();this.smoke.splice(i,1);}}
 this.light.intensity*=Math.exp(-dt*12);
 }
}
